import pathlib, subprocess, re, shutil, os
repo='/home/runner/grit'; root=pathlib.Path('/tmp/4184-source'); bins=pathlib.Path('/tmp/4184-bins')
files=['grit-lib/src/branch_inventory.rs','grit-lib/src/repo.rs','grit-lib/src/worktree/core.rs','grit-lib/src/refs/mod.rs','grit-lib/src/refs/store/files.rs']
def show(rev,f): return subprocess.check_output(['git','show',f'{rev}:{f}'],cwd=repo).decode()
base={f:show('818de8006',f) for f in files}; end={f:show('c8f1565',f) for f in files}
for name in os.environ.get('VARIANTS','before,a,b,c,all,noop').split(','):
    content=dict(base)
    if name in ['a','all']:
        for f in files[:3]:content[f]=end[f]
    if name in ['b','c','all']:
        f=files[3]; s=end[f]
        if name=='b':
            old=base[f]; start=old.index('    fn map_for_prefix_filtered('); stop=old.index('\n}\n',start)
            method=old[start:stop]
            method=method.replace('parse_packed_refs_region(path, region, prefix_trim, keep, self.peel_trait)', 'parse_packed_refs_region(path, region, prefix_trim, keep, self.peel_trait).map(|(map, _)| map)')
            start=s.index('    fn map_for_prefix_filtered('); stop=s.index('    /// Strictly parse the lines',start)
            s=s[:start]+method+'\n\n'+s[stop:]
        if name=='c':
            start=s.index('    /// Collect a full scan in file order'); stop=s.index('    /// [`Self::map_for_prefix`]',start)
            s=s[:start]+s[stop:]
        content[f]=s
        if name in ['b','all']: content[files[4]]=end[files[4]]
    if name=='noop':
        f=files[0]; s=base[f]
        a=s.index('fn ref_query_options('); b=s.index('fn ref_query_error(',a); c=s.index('fn branch_worktree_paths(',b)
        content[f]=s[:a]+s[b:c]+s[a:b]+s[c:]
    for f,s in content.items():(root/f).write_text(s)
    env=dict(os.environ,CARGO_TARGET_DIR='/home/runner/grit/target',CARGO_BUILD_JOBS='4')
    with open(f'/tmp/4184-build-{name}.log','w') as log:
        result=subprocess.run(['cargo','build','--release','-p','grit-cli','-p','grit-utils'],cwd=root,env=env,stdout=log,stderr=subprocess.STDOUT)
    if result.returncode: raise SystemExit(f'{name} build failed')
    for binary in ['grit','grit-bench']:
        shutil.copy2('/home/runner/grit/target/release/'+binary,bins/(binary+'-'+name))
    print(name+' built',flush=True)

