import subprocess, pathlib, os, json, random, statistics, time, sys
root=pathlib.Path('/tmp/4184-fixtures'); bins=pathlib.Path('/tmp/4184-bins')
variants=sys.argv[1].split(',') if len(sys.argv)>1 else ['before','a','b','c','all']
runs=int(os.environ.get('RUNS','60')); out=os.environ.get('OUTPUT','/tmp/4184-bisect.json')
env=dict(os.environ,GIT_CONFIG_NOSYSTEM='1',GIT_CONFIG_GLOBAL='/dev/null',GIT_CONFIG_SYSTEM='/dev/null',GIT_TERMINAL_PROMPT='0')
rows=['status/clean@small-confirm','branch/merged-ref@many-refs-confirm','branch/list@many-refs-confirm','branch/create@many-refs','branch/delete@many-refs','branch/rename@many-refs','tag/create@many-refs']
if os.environ.get('FULL'):
 rows+=['branch/list-json@many-refs','branch/merged@many-refs','branch/list@many-refs-loose','tag/list@many-refs','ref/list@many-refs','branch/list@local-6667','branch/list@100k-local','ref/list@100k','branch/list@local-loose-6667','tag/list@100k']
def run(cmd,cwd,**kw):
 r=subprocess.run(cmd,cwd=cwd,env=env,stdout=subprocess.DEVNULL,stderr=subprocess.PIPE,**kw)
 if r.returncode:raise RuntimeError(str(cmd)+' '+r.stderr.decode())
 return r
result={'method':f'{runs} interleaved direct-spawn runs/tool, seed 4184; 10 warmups/tool; max RSS of 10 /usr/bin/time -v samples','variants':variants,'rows':{}}
rng=random.Random(4184)
for row in rows:
 op,shape=row.split('@'); shape=shape.removesuffix('-confirm')
 cwd=root/shape
 if shape=='local-6667':cwd=pathlib.Path(os.path.expanduser('~/.cache/grit-bench/many-refs'))
 if shape=='local-loose-6667':cwd=pathlib.Path(os.path.expanduser('~/.cache/grit-bench/many-refs-loose'))
 if shape=='100k-local':cwd=root/'100k-local'
 if shape=='100k':cwd=root/'100k'
 head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=cwd,env=env).decode().strip()
 tools=['git']+variants
 def prepare():
  if op in ['branch/create','branch/delete','branch/rename']:
   for name in ['speed-bench','speed-renamed']:
    run(['git','update-ref','-d','refs/heads/'+name],cwd)
   if op!='branch/create':run(['git','update-ref','refs/heads/speed-bench',head],cwd)
  if op=='tag/create':run(['git','update-ref','-d','refs/tags/speed-bench'],cwd)
 def command(tool):
  git=tool=='git'; cli='git' if git else str(bins/('grit-'+tool)); bench=str(bins/('grit-bench-'+tool))
  if not git and os.environ.get('MATCHED_PATHS'):
   slot=['before','a','b','c','all','noop','main-before','main-after'].index(tool)
   cli=str(bins/f'v{slot}'/'grit'); bench=str(bins/f'v{slot}'/'grit-bench')
  if op=='status/clean':return [cli,'status']
  if op=='branch/list':return [cli,'branch']
  if op=='branch/list-json':return [cli,'branch','-vv'] if git else [cli,'branch','--json']
  if op=='branch/merged':return [cli,'branch','--merged','main']
  if op=='branch/merged-ref':return ['git','for-each-ref','refs/heads/','--merged='+head,'--format=%(refname)'] if git else [bench,'refs-driver','ref-query',str(cwd),'--namespace','heads','--merged',head]
  if op=='branch/create':return [cli,'branch','speed-bench']
  if op=='branch/delete':return [cli,'branch','-D','speed-bench']
  if op=='branch/rename':return [cli,'branch','-m','speed-bench','speed-renamed'] if git else [bench,'rename-branch-lib','--repo',str(cwd),'--old','speed-bench','--new','speed-renamed']
  if op=='tag/create':return [cli,'tag','speed-bench']
  if op=='tag/list':return [cli,'tag','-l','--sort=version:refname'] if git else [cli,'tag']
  if op=='ref/list':return [cli,'for-each-ref'] if git else [bench,'refs-driver','for-each-ref',str(cwd)]
 samples={t:[] for t in tools}
 for i in range(10):
  for t in tools:prepare();run(command(t),cwd)
 for i in range(runs):
  rng.shuffle(tools)
  for t in tools:
   prepare();start=time.perf_counter_ns();run(command(t),cwd);samples[t].append((time.perf_counter_ns()-start)/1e6)
 record={'cwd':str(cwd),'tools':{}}
 for t in tools:
  rss=[]
  for i in range(10):
   prepare();r=run(['/usr/bin/time','-v',*command(t)],cwd)
   rss.append(int(next(l.split(':',1)[1] for l in r.stderr.decode().splitlines() if 'Maximum resident' in l)))
  record['tools'][t]={'command':command(t),'median_ms':statistics.median(samples[t]),'runs_ms':samples[t],'rss_kb':max(rss)}
 result['rows'][row]=record
 pathlib.Path(out).write_text(json.dumps(result,indent=2)+'\n')
 print(row,' '.join(f'{t}={statistics.median(samples[t]):.3f}' for t in ['git']+variants),flush=True)

