#include <stddef.h>
#include <stdatomic.h>
#include <stdio.h>
extern void *__libc_malloc(size_t);
extern void *__libc_calloc(size_t,size_t);
extern void *__libc_realloc(void*,size_t);
extern void __libc_free(void*);
static _Atomic unsigned long calls, bytes;
void *malloc(size_t n) { atomic_fetch_add(&calls,1); atomic_fetch_add(&bytes,n); return __libc_malloc(n); }
void *calloc(size_t n,size_t s) { atomic_fetch_add(&calls,1); atomic_fetch_add(&bytes,n*s); return __libc_calloc(n,s); }
void *realloc(void *p,size_t n) { atomic_fetch_add(&calls,1); atomic_fetch_add(&bytes,n); return __libc_realloc(p,n); }
void free(void *p) { __libc_free(p); }
__attribute__((destructor)) static void report(void) { fprintf(stderr,"allocations=%lu requested_bytes=%lu\n",atomic_load(&calls),atomic_load(&bytes)); }

